param(
    [Parameter(ValueFromRemainingArguments = $true)]
    [string[]]$CliArgs
)

$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$RootDir    = $PSScriptRoot
$ServerDir  = Join-Path $RootDir "server"
$ModsDir    = Join-Path $ServerDir "mods"
$PluginsDir = Join-Path $ServerDir "plugins"
$RuntimeDir = Join-Path $RootDir "runtime"
$PlayitDir  = Join-Path $RootDir "playit"
$WebDir     = Join-Path $RootDir "web_panel"
$LogsDir    = Join-Path $RootDir "logs"
$ConfigFile = Join-Path $RootDir "server_config.json"

$EmbeddedIndexHtmlB64 = ""
$EmbeddedWebServerJavaB64 = ""

function Write-Utf8NoBom($Path, $Content) {
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }
    [System.IO.File]::WriteAllText($Path, $Content, (New-Object System.Text.UTF8Encoding $false))
}

function Decompress-B64ToBytes($b64) {
    $gzBytes = [Convert]::FromBase64String($b64)
    $msIn = New-Object System.IO.MemoryStream(,$gzBytes)
    $gz = New-Object System.IO.Compression.GZipStream($msIn, [System.IO.Compression.CompressionMode]::Decompress)
    $msOut = New-Object System.IO.MemoryStream
    $gz.CopyTo($msOut)
    $gz.Close()
    $msIn.Close()
    return $msOut.ToArray()
}

function Extract-WebGuiFiles {
    if (-not (Test-Path $WebDir)) { New-Item -ItemType Directory -Path $WebDir -Force | Out-Null }
    $htmlBytes = Decompress-B64ToBytes $EmbeddedIndexHtmlB64
    $javaBytes = Decompress-B64ToBytes $EmbeddedWebServerJavaB64
    [System.IO.File]::WriteAllBytes((Join-Path $WebDir "index.html"), $htmlBytes)
    [System.IO.File]::WriteAllBytes((Join-Path $WebDir "WebServer.java"), $javaBytes)
}

function Get-DefaultConfig {
    return [ordered]@{
        mc_version   = "1.21.11"
        loader       = "fabric"
        ram_min_mb   = 4096
        ram_max_mb   = 6144
        flag_profile = "meowice_g1gc"
        server_jar   = "server.jar"
        web_port     = 8888
        auto_playit  = $true
    }
}

function Load-Config {
    if (-not (Test-Path $ConfigFile)) {
        return (Get-DefaultConfig)
    }
    $raw = Get-Content -Path $ConfigFile -Raw -Encoding UTF8
    $obj = $raw | ConvertFrom-Json
    return [ordered]@{
        mc_version   = if ($obj.mc_version) { [string]$obj.mc_version } else { "1.21.11" }
        loader       = if ($obj.loader) { ([string]$obj.loader).ToLower() } else { "fabric" }
        ram_min_mb   = if ($obj.ram_min_mb) { [int]$obj.ram_min_mb } else { 4096 }
        ram_max_mb   = if ($obj.ram_max_mb) { [int]$obj.ram_max_mb } else { 6144 }
        flag_profile = if ($obj.flag_profile) { [string]$obj.flag_profile } else { "meowice_g1gc" }
        server_jar   = if ($obj.server_jar) { [string]$obj.server_jar } else { "server.jar" }
        web_port     = if ($obj.web_port) { [int]$obj.web_port } else { 8888 }
        auto_playit  = if ($null -ne $obj.auto_playit) { [bool]$obj.auto_playit } else { $true }
    }
}

function Save-Config($cfg) {
    Write-Utf8NoBom $ConfigFile ($cfg | ConvertTo-Json -Depth 4)
}

function Get-JavaMajorVersion($javaExe) {
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $javaExe
        $psi.Arguments = "-version"
        $psi.RedirectStandardError = $true
        $psi.RedirectStandardOutput = $true
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $p = [System.Diagnostics.Process]::Start($psi)
        $err = $p.StandardError.ReadToEnd()
        $p.WaitForExit()
        if ($err -match 'version "(\d+)') {
            return [int]$Matches[1]
        }
    } catch {}
    return 0
}

function Get-JavaPath {
    if (Test-Path $RuntimeDir) {
        $localJava = Get-ChildItem -Path $RuntimeDir -Filter "java.exe" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($localJava -and (Get-JavaMajorVersion $localJava.FullName) -ge 21) {
            return $localJava.FullName
        }
    }
    $sysJava = Get-Command "java.exe" -ErrorAction SilentlyContinue
    if ($sysJava -and (Get-JavaMajorVersion $sysJava.Source) -ge 21) {
        return $sysJava.Source
    }
    return $null
}

function Get-CpuArch {
    $arch = ($env:PROCESSOR_ARCHITECTURE + "").ToUpper()
    if ($arch -match "ARM64|AARCH64") { return "aarch64" }
    return "amd64"
}

function Get-JvmFlagsList($cfg) {
    $profile = $cfg.flag_profile
    $ramMax  = [int]$cfg.ram_max_mb
    $isArm64 = (Get-CpuArch) -eq "aarch64"
    $flags   = New-Object System.Collections.Generic.List[string]

    if ($profile -eq "default") {
        return $flags
    }

    if ($profile -eq "etil_flags") {
        $highRam = $ramMax -gt 12288
        $etil = @(
            "-XX:+UseG1GC", "-XX:+ParallelRefProcEnabled", "-XX:MaxGCPauseMillis=200",
            "-XX:+UnlockExperimentalVMOptions", "-XX:+UnlockDiagnosticVMOptions", "-XX:+IgnoreUnrecognizedVMOptions",
            "-XX:+DisableExplicitGC", "-XX:+AlwaysPreTouch",
            "-XX:G1NewSizePercent=" + $(if ($highRam) { "40" } else { "30" }),
            "-XX:G1MaxNewSizePercent=" + $(if ($highRam) { "50" } else { "40" }),
            "-XX:G1HeapRegionSize=" + $(if ($highRam) { "16M" } else { "8M" }),
            "-XX:G1ReservePercent=" + $(if ($highRam) { "15" } else { "20" }),
            "-XX:G1HeapWastePercent=5", "-XX:G1MixedGCCountTarget=4",
            "-XX:InitiatingHeapOccupancyPercent=" + $(if ($highRam) { "20" } else { "15" }),
            "-XX:G1MixedGCLiveThresholdPercent=90", "-XX:G1RSetUpdatingPauseTimePercent=5",
            "-XX:SurvivorRatio=32", "-XX:+PerfDisableSharedMem", "-XX:MaxTenuringThreshold=1",
            "-XX:-UseBiasedLocking", "-XX:UseAVX=3", "-XX:+UseStringDeduplication",
            "-XX:+UseFastUnorderedTimeStamps", "-XX:+UseAES", "-XX:+UseAESIntrinsics",
            "-XX:UseSSE=4", "-XX:+UseFMA", "-XX:AllocatePrefetchStyle=1",
            "-XX:+UseLoopPredicate", "-XX:+RangeCheckElimination", "-XX:+EliminateLocks",
            "-XX:+DoEscapeAnalysis", "-XX:+UseCodeCacheFlushing", "-XX:+SegmentedCodeCache",
            "-XX:+UseFastJNIAccessors", "-XX:+OptimizeStringConcat", "-XX:+UseCompressedOops",
            "-XX:+UseThreadPriorities", "-XX:+OmitStackTraceInFastThrow",
            "-XX:+TrustFinalNonStaticFields", "-XX:ThreadPriorityPolicy=1",
            "-XX:+UseInlineCaches", "-XX:+RewriteBytecodes", "-XX:+RewriteFrequentPairs",
            "-XX:+UseNUMA", "-XX:-DontCompileHugeMethods", "-XX:+UseFPUForSpilling",
            "-XX:+UseFastStosb", "-XX:+UseNewLongLShift", "-XX:+UseVectorCmov",
            "-XX:+UseXMMForArrayCopy", "-XX:+UseXmmI2D", "-XX:+UseXmmI2F",
            "-XX:+UseXmmLoadAndClearUpper", "-XX:+UseXmmRegToRegMoveAll",
            "-Dfile.encoding=UTF-8", "-Djava.security.egd=file:/dev/urandom",
            "--add-modules=jdk.incubator.vector"
        )
        $x86Only = @("-XX:+UseFastStosb","-XX:+UseXmmI2D","-XX:+UseXmmI2F","-XX:+UseXmmLoadAndClearUpper","-XX:+UseXmmRegToRegMoveAll","-XX:UseAVX=3","-XX:UseSSE=4")
        foreach ($f in $etil) {
            if ($isArm64 -and ($x86Only -contains $f)) { continue }
            $flags.Add($f)
        }
        return $flags
    }

    if ($profile -eq "aikar") {
        $aikar = @(
            "--add-modules=jdk.incubator.vector",
            "-XX:+UseG1GC", "-XX:+ParallelRefProcEnabled", "-XX:MaxGCPauseMillis=200",
            "-XX:+UnlockExperimentalVMOptions", "-XX:+IgnoreUnrecognizedVMOptions",
            "-XX:+DisableExplicitGC", "-XX:+AlwaysPreTouch",
            "-XX:G1NewSizePercent=30", "-XX:G1MaxNewSizePercent=40",
            "-XX:G1HeapRegionSize=8M", "-XX:G1ReservePercent=20",
            "-XX:G1HeapWastePercent=5", "-XX:G1MixedGCCountTarget=4",
            "-XX:InitiatingHeapOccupancyPercent=15", "-XX:G1MixedGCLiveThresholdPercent=90",
            "-XX:G1RSetUpdatingPauseTimePercent=5", "-XX:SurvivorRatio=32",
            "-XX:+PerfDisableSharedMem", "-XX:MaxTenuringThreshold=1",
            "-Dusing.aikars.flags=https://mcflags.emc.gs", "-Daikars.new.flags=true"
        )
        foreach ($f in $aikar) { $flags.Add($f) }
        return $flags
    }

    # MeowIce Flags (https://github.com/MeowIce/meowice-flags)
    $flags.Add("--add-modules=jdk.incubator.vector")
    if ($profile -eq "meowice_zgc") {
        $softMax = [Math]::Max(1024, $ramMax - 2048)
        $gcPart = @(
            "-XX:+UseZGC", "-XX:-ZProactive", "-XX:SoftMaxHeapSize=$($softMax)M",
            "-XX:+UnlockExperimentalVMOptions", "-XX:+UnlockDiagnosticVMOptions", "-XX:+IgnoreUnrecognizedVMOptions",
            "-XX:+DisableExplicitGC", "-XX:+AlwaysPreTouch", "-XX:+PerfDisableSharedMem", "-XX:+UseNUMA",
            "-XX:-DontCompileHugeMethods", "-XX:MaxNodeLimit=240000", "-XX:NodeLimitFudgeFactor=8000",
            "-XX:ReservedCodeCacheSize=400M", "-XX:NonNMethodCodeHeapSize=12M",
            "-XX:ProfiledCodeHeapSize=194M", "-XX:NonProfiledCodeHeapSize=194M",
            "-XX:NmethodSweepActivity=1", "-XX:+UseCriticalJavaThreadPriority",
            "-XX:AllocatePrefetchStyle=1", "-XX:+AlwaysActAsServerClassMachine",
            "-XX:+UseTransparentHugePages", "-XX:LargePageSizeInBytes=2M", "-XX:+UseLargePages",
            "-XX:+EagerJVMCI", "-XX:+UseStringDeduplication"
        )
    } else {
        $gcPart = @(
            "-XX:+UseG1GC", "-XX:MaxGCPauseMillis=200",
            "-XX:+UnlockExperimentalVMOptions", "-XX:+UnlockDiagnosticVMOptions", "-XX:+IgnoreUnrecognizedVMOptions",
            "-XX:+DisableExplicitGC", "-XX:+AlwaysPreTouch",
            "-XX:G1NewSizePercent=28", "-XX:G1MaxNewSizePercent=50", "-XX:G1HeapRegionSize=16M",
            "-XX:G1ReservePercent=15", "-XX:G1MixedGCCountTarget=3", "-XX:InitiatingHeapOccupancyPercent=20",
            "-XX:G1MixedGCLiveThresholdPercent=90", "-XX:SurvivorRatio=32", "-XX:G1HeapWastePercent=5",
            "-XX:+PerfDisableSharedMem", "-XX:G1SATBBufferEnqueueingThresholdPercent=30",
            "-XX:G1ConcMarkStepDurationMillis=5", "-XX:G1RSetUpdatingPauseTimePercent=0",
            "-XX:+UseNUMA", "-XX:-DontCompileHugeMethods", "-XX:MaxNodeLimit=240000",
            "-XX:NodeLimitFudgeFactor=8000", "-XX:ReservedCodeCacheSize=400M",
            "-XX:NonNMethodCodeHeapSize=12M", "-XX:ProfiledCodeHeapSize=194M",
            "-XX:NonProfiledCodeHeapSize=194M", "-XX:NmethodSweepActivity=1",
            "-XX:+UseCriticalJavaThreadPriority", "-XX:AllocatePrefetchStyle=3",
            "-XX:+AlwaysActAsServerClassMachine", "-XX:+UseTransparentHugePages",
            "-XX:LargePageSizeInBytes=2M", "-XX:+UseLargePages",
            "-XX:+EagerJVMCI", "-XX:+UseStringDeduplication"
        )
    }

    $commonPart = @(
        "-XX:+UseAES", "-XX:+UseAESIntrinsics", "-XX:+UseFMA", "-XX:+UseLoopPredicate",
        "-XX:+RangeCheckElimination", "-XX:+OptimizeStringConcat", "-XX:+UseCompressedOops",
        "-XX:+UseThreadPriorities", "-XX:+OmitStackTraceInFastThrow", "-XX:+RewriteBytecodes",
        "-XX:+RewriteFrequentPairs", "-XX:+UseFPUForSpilling", "-XX:+UseFastStosb",
        "-XX:+UseNewLongLShift", "-XX:+UseVectorCmov", "-XX:+UseXMMForArrayCopy",
        "-XX:+UseXmmI2D", "-XX:+UseXmmI2F", "-XX:+UseXmmLoadAndClearUpper",
        "-XX:+UseXmmRegToRegMoveAll", "-XX:+EliminateLocks", "-XX:+DoEscapeAnalysis",
        "-XX:+AlignVector", "-XX:+OptimizeFill", "-XX:+EnableVectorSupport",
        "-XX:+UseCharacterCompareIntrinsics", "-XX:+UseCopySignIntrinsic", "-XX:+UseVectorStubs",
        "-XX:UseAVX=2", "-XX:UseSSE=4", "-XX:+UseFastJNIAccessors",
        "-XX:+UseInlineCaches", "-XX:+SegmentedCodeCache", "-XX:+UseCompactObjectHeaders",
        "-Djdk.nio.maxCachedBufferSize=262144",
        "-Djdk.graal.UsePriorityInlining=true", "-Djdk.graal.Vectorization=true",
        "-Djdk.graal.OptDuplication=true", "-Djdk.graal.DetectInvertedLoopsAsCounted=true",
        "-Djdk.graal.LoopInversion=true", "-Djdk.graal.VectorizeHashes=true",
        "-Djdk.graal.StripMineNonCountedLoops=true", "-Djdk.graal.SpeculativeGuardMovement=true",
        "-Djdk.graal.TuneInlinerExploration=1", "-Djdk.graal.LoopRotation=true",
        "-Djdk.graal.CompilerConfiguration=community", "-DLeaf.enableFMA=true"
    )

    $x86Meow = @("-XX:+UseFastStosb","-XX:+UseXmmI2D","-XX:+UseXmmI2F","-XX:+UseXmmLoadAndClearUpper","-XX:+UseXmmRegToRegMoveAll","-XX:UseAVX=2","-XX:UseSSE=4")
    foreach ($f in ($gcPart + $commonPart)) {
        if ($isArm64 -and ($x86Meow -contains $f)) { continue }
        $flags.Add($f)
    }
    return $flags
}

function Ensure-EulaAndProperties {
    if (-not (Test-Path $ServerDir)) { New-Item -ItemType Directory -Path $ServerDir -Force | Out-Null }
    Write-Utf8NoBom (Join-Path $ServerDir "eula.txt") "eula=true`n"
    $propPath = Join-Path $ServerDir "server.properties"
    if (-not (Test-Path $propPath)) {
        $defProp = @(
            "online-mode=false",
            "max-players=20",
            "gamemode=survival",
            "difficulty=normal",
            "server-port=25565",
            "view-distance=10",
            "pvp=true",
            "white-list=false",
            "motd=Minecraft 1.21.11 Server - MeowIce Flags + Playit.gg"
        ) -join "`n"
        Write-Utf8NoBom $propPath ($defProp + "`n")
    }
}

function Find-ForgeArgsFile($fileName) {
    $libs = Join-Path $ServerDir "libraries"
    if (-not (Test-Path $libs)) { return $null }
    $hit = Get-ChildItem -Path $libs -Filter $fileName -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($hit) {
        return $hit.FullName.Substring($ServerDir.Length + 1)
    }
    return $null
}

function Update-StartupScripts($cfg) {
    if (-not (Test-Path $ServerDir)) { New-Item -ItemType Directory -Path $ServerDir -Force | Out-Null }
    $flagsList = Get-JvmFlagsList $cfg
    $flagsStr  = $flagsList -join " "
    $minMb     = $cfg.ram_min_mb
    $maxMb     = $cfg.ram_max_mb
    $loader    = $cfg.loader
    $jar       = $cfg.server_jar

    $jvmArgsLines = @("# Auto-generated by MC Server Manager", "-Xms$($minMb)M", "-Xmx$($maxMb)M") + $flagsList
    Write-Utf8NoBom (Join-Path $ServerDir "user_jvm_args.txt") (($jvmArgsLines -join "`n") + "`n")

    $winArgs  = Find-ForgeArgsFile "win_args.txt"
    $unixArgs = Find-ForgeArgsFile "unix_args.txt"

    if (($loader -eq "forge" -or $loader -eq "neoforge") -and $winArgs) {
        $winTarget = "@user_jvm_args.txt @$winArgs nogui"
    } else {
        $winTarget = "-Xms$($minMb)M -Xmx$($maxMb)M $flagsStr -jar $jar nogui"
    }

    if (($loader -eq "forge" -or $loader -eq "neoforge") -and $unixArgs) {
        $unixTarget = "@user_jvm_args.txt @$($unixArgs -replace '\\','/') nogui"
    } else {
        $unixTarget = "-Xms$($minMb)M -Xmx$($maxMb)M $flagsStr -jar $jar nogui"
    }

    $bat = @(
        "@echo off",
        "cd /d ""%~dp0""",
        "set ""JAVA_BIN=java""",
        "for /f ""delims="" %%J in ('dir /b /s ""%~dp0..\runtime\java.exe"" 2^>nul') do set ""JAVA_BIN=%%J""",
        """%JAVA_BIN%"" $winTarget",
        "pause"
    ) -join "`r`n"
    Set-Content -Path (Join-Path $ServerDir "start_server.bat") -Value $bat -Encoding ASCII

    $sh = @(
        "#!/usr/bin/env bash",
        "cd ""`$(dirname ""`$0"")""",
        "JAVA_BIN=""`$(find ../runtime -type f -name java 2>/dev/null | head -n 1)""",
        "if [ -z ""`$JAVA_BIN"" ]; then JAVA_BIN=""java""; fi",
        "exec ""`$JAVA_BIN"" $unixTarget"
    ) -join "`n"
    Write-Utf8NoBom (Join-Path $ServerDir "start_server.sh") ($sh + "`n")
}

function Download-Silent($url, $dest) {
    $parent = Split-Path -Parent $dest
    if (-not (Test-Path $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
    Invoke-WebRequest -Uri $url -OutFile $dest -UseBasicParsing -Headers @{ "User-Agent" = "MC-Server-Manager-VN/1.0" }
}

function Install-JavaSilent {
    if (Get-JavaPath) { return }
    if (-not (Test-Path $RuntimeDir)) { New-Item -ItemType Directory -Path $RuntimeDir -Force | Out-Null }
    $arch = Get-CpuArch
    $dlUrl = $null
    $outZip = Join-Path $RuntimeDir "java_pkg.zip"

    if ($arch -eq "amd64") {
        try {
            $rel = Invoke-RestMethod -Uri "https://api.github.com/repos/graalvm/graalvm-ce-builds/releases/latest" -Headers @{ "User-Agent" = "MC-Server-Manager-VN/1.0" }
            $asset = $rel.assets | Where-Object { $_.name -like "*windows-x64_bin.zip" } | Select-Object -First 1
            if ($asset) { $dlUrl = $asset.browser_download_url }
        } catch {}
    }

    if (-not $dlUrl) {
        $adArch = if ($arch -eq "aarch64") { "aarch64" } else { "x64" }
        $dlUrl = "https://api.adoptium.net/v3/binary/latest/21/ga/windows/$adArch/jdk/hotspot/normal/eclipse"
    }

    Download-Silent $dlUrl $outZip
    Expand-Archive -Path $outZip -DestinationPath $RuntimeDir -Force
    Remove-Item -Path $outZip -Force -ErrorAction SilentlyContinue
}

function Install-ServerLoaderSilent($ver, $loader) {
    if (-not (Test-Path $ServerDir)) { New-Item -ItemType Directory -Path $ServerDir -Force | Out-Null }
    if (-not (Test-Path $ModsDir)) { New-Item -ItemType Directory -Path $ModsDir -Force | Out-Null }
    if (-not (Test-Path $PluginsDir)) { New-Item -ItemType Directory -Path $PluginsDir -Force | Out-Null }
    Ensure-EulaAndProperties
    $loader = $loader.ToLower()
    $jarOut = Join-Path $ServerDir "server.jar"

    switch ($loader) {
        "fabric" {
            $loaders = Invoke-RestMethod -Uri "https://meta.fabricmc.net/v2/versions/loader"
            $insts   = Invoke-RestMethod -Uri "https://meta.fabricmc.net/v2/versions/installer"
            $lVer = $loaders[0].version
            $iVer = $insts[0].version
            Download-Silent "https://meta.fabricmc.net/v2/versions/loader/$ver/$lVer/$iVer/server/jar" $jarOut
        }
        "paper" {
            $builds = Invoke-RestMethod -Uri "https://fill.papermc.io/v3/projects/paper/versions/$ver/builds"
            $url = $builds[0].downloads.'server:default'.url
            Download-Silent $url $jarOut
        }
        "purpur" {
            Download-Silent "https://api.purpurmc.org/v2/purpur/$ver/latest/download" $jarOut
        }
        "leaf" {
            $proj = Invoke-RestMethod -Uri "https://api.leafmc.one/v2/projects/leaf"
            if (-not ($proj.versions -contains $ver)) {
                throw "LeafMC chua ho tro phien ban $ver. Cac ban co san: $($proj.versions -join ', ')"
            }
            $vInfo  = Invoke-RestMethod -Uri "https://api.leafmc.one/v2/projects/leaf/versions/$ver"
            $latest = $vInfo.builds[-1]
            $bInfo  = Invoke-RestMethod -Uri "https://api.leafmc.one/v2/projects/leaf/versions/$ver/builds/$latest"
            $jName  = $bInfo.downloads.application.name
            Download-Silent "https://api.leafmc.one/v2/projects/leaf/versions/$ver/builds/$latest/downloads/$jName" $jarOut
        }
        "neoforge" {
            Install-JavaSilent
            $jExe = Get-JavaPath
            $nf   = Invoke-RestMethod -Uri "https://maven.neoforged.net/api/maven/versions/releases/net/neoforged/neoforge"
            $parts = $ver.Split('.')
            $prefix = if ($parts.Length -ge 3 -and $parts[0] -eq "1") { "$($parts[1]).$($parts[2])." } elseif ($parts.Length -ge 2 -and $parts[0] -eq "1") { "$($parts[1]).0." } else { $ver }
            $match = ($nf.versions | Where-Object { $_ -like "$prefix*" } | Select-Object -Last 1)
            if (-not $match) { throw "Khong tim thay NeoForge cho phien ban $ver" }
            $instJar = Join-Path $ServerDir "neoforge-installer.jar"
            Download-Silent "https://maven.neoforged.net/releases/net/neoforged/neoforge/$match/neoforge-$match-installer.jar" $instJar
            Push-Location $ServerDir
            & $jExe -jar $instJar --installServer | Out-Null
            Pop-Location
            Remove-Item $instJar -Force -ErrorAction SilentlyContinue
        }
        "forge" {
            Install-JavaSilent
            $jExe   = Get-JavaPath
            $promos = (Invoke-RestMethod -Uri "https://files.minecraftforge.net/net/minecraftforge/forge/promotions_slim.json").promos
            $fv = $promos."$ver-recommended"
            if (-not $fv) { $fv = $promos."$ver-latest" }
            if (-not $fv) { throw "Khong tim thay Forge cho phien ban $ver" }
            $full = "$ver-$fv"
            $instJar = Join-Path $ServerDir "forge-installer.jar"
            Download-Silent "https://maven.minecraftforge.net/net/minecraftforge/forge/$full/forge-$full-installer.jar" $instJar
            Push-Location $ServerDir
            & $jExe -jar $instJar --installServer | Out-Null
            Pop-Location
            Remove-Item $instJar -Force -ErrorAction SilentlyContinue
        }
        "vanilla" {
            $manifest = Invoke-RestMethod -Uri "https://piston-meta.mojang.com/mc/game/version_manifest_v2.json"
            $entry = $manifest.versions | Where-Object { $_.id -eq $ver } | Select-Object -First 1
            if (-not $entry) { throw "Khong tim thay Vanilla MC $ver" }
            $vData = Invoke-RestMethod -Uri $entry.url
            Download-Silent $vData.downloads.server.url $jarOut
        }
        default { throw "Loader khong hop le: $loader" }
    }
}

function Install-PlayitSilent {
    if (-not (Test-Path $PlayitDir)) { New-Item -ItemType Directory -Path $PlayitDir -Force | Out-Null }
    $dlUrl = "https://github.com/playit-cloud/playit-agent/releases/download/v2.0.2/playit-windows-x86_64-signed.exe"
    try {
        $rel = Invoke-RestMethod -Uri "https://api.github.com/repos/playit-cloud/playit-agent/releases/latest" -Headers @{ "User-Agent" = "MC-Server-Manager-VN/1.0" }
        $asset = $rel.assets | Where-Object { $_.name -eq "playit-windows-x86_64-signed.exe" } | Select-Object -First 1
        if ($asset) { $dlUrl = $asset.browser_download_url }
    } catch {}
    Download-Silent $dlUrl (Join-Path $PlayitDir "playit.exe")
}

function Install-ModrinthSilent($slug, $ver, $loader) {
    $isPlugin = @("paper","purpur","leaf") -contains $loader.ToLower()
    $targetDir = if ($isPlugin) { $PluginsDir } else { $ModsDir }
    if (-not (Test-Path $targetDir)) { New-Item -ItemType Directory -Path $targetDir -Force | Out-Null }

    $versions = Invoke-RestMethod -Uri "https://api.modrinth.com/v2/project/$slug/version" -Headers @{ "User-Agent" = "MC-Server-Manager-VN/1.0" }
    $chosen = $versions | Where-Object { ($_.loaders -contains $loader) -and ($_.game_versions -contains $ver) } | Select-Object -First 1
    if (-not $chosen) { $chosen = $versions | Where-Object { $_.loaders -contains $loader } | Select-Object -First 1 }
    if (-not $chosen) { $chosen = $versions | Select-Object -First 1 }
    if (-not $chosen) { throw "Khong tim thay file phu hop cho $slug" }

    $f = $chosen.files | Where-Object { $_.primary -eq $true } | Select-Object -First 1
    if (-not $f) { $f = $chosen.files[0] }
    $safeName = [System.IO.Path]::GetFileName($f.filename) -replace '[^a-zA-Z0-9._-]','_'
    Download-Silent $f.url (Join-Path $targetDir $safeName)
}

function Install-PackSilent($packType, $ver, $loader) {
    if ($packType -eq "mod_opt") {
        foreach ($s in @("fabric-api","lithium","ferrite-core","spark","chunky")) {
            try { Install-ModrinthSilent $s $ver $loader } catch {}
        }
    } elseif ($packType -eq "plugin_base") {
        foreach ($s in @("spark","chunky","viaversion","viabackwards","luckperms")) {
            try { Install-ModrinthSilent $s $ver $loader } catch {}
        }
    }
}

# ==================== BACKGROUND SILENT RUNNER WITH TIMER ====================

function Invoke-SilentTask($Title, [string[]]$TaskArgs) {
    if (-not (Test-Path $LogsDir)) { New-Item -ItemType Directory -Path $LogsDir -Force | Out-Null }
    $outLog = Join-Path $LogsDir "install_out.log"
    $errLog = Join-Path $LogsDir "install_err.log"
    Remove-Item $outLog, $errLog -Force -ErrorAction SilentlyContinue

    $argList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $PSCommandPath, "--run-task") + $TaskArgs
    $proc = Start-Process -FilePath "powershell.exe" -ArgumentList $argList -WindowStyle Hidden -PassThru -RedirectStandardOutput $outLog -RedirectStandardError $errLog

    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    Write-Host ""
    while (-not $proc.HasExited) {
        $t = "{0:00}:{1:00}s" -f [int]$sw.Elapsed.TotalMinutes, $sw.Elapsed.Seconds
        Write-Host -NoNewline ("`r  [DANG CAI DAT] $Title... | Thoi gian: $t   ")
        Start-Sleep -Milliseconds 250
    }
    $sw.Stop()
    $total = "{0:00}:{1:00}s" -f [int]$sw.Elapsed.TotalMinutes, $sw.Elapsed.Seconds
    Write-Host -NoNewline "`r                                                                                `r"

    if ($proc.ExitCode -eq 0) {
        Write-Host "  [HOAN THANH] Cai dat thanh cong $Title! (Tong thoi gian: $total)" -ForegroundColor Green
    } else {
        Write-Host "  [LOI] Qua trinh cai dat '$Title' that bai sau $total." -ForegroundColor Red
        if (Test-Path $errLog) {
            $errText = Get-Content $errLog -Raw -ErrorAction SilentlyContinue
            if ($errText) { Write-Host ("  Chi tiet: " + ($errText.Trim().Split("`n")[-1])) -ForegroundColor Yellow }
        }
    }
}

# ==================== CLI INTERNAL DISPATCH ====================

if ($CliArgs.Count -gt 0) {
    if ($CliArgs[0] -eq "--help" -or $CliArgs[0] -eq "-h") {
        Write-Host "Su dung: install_windows.bat [--test-config | --help]"
        exit 0
    }
    if ($CliArgs[0] -eq "--test-config") {
        $cfg = Load-Config
        $g1 = (Get-JvmFlagsList $cfg) -join " "
        $cfgZ = @{ flag_profile = "meowice_zgc"; ram_max_mb = 32768 }
        $zgc = (Get-JvmFlagsList $cfgZ) -join " "
        $cfgE = @{ flag_profile = "etil_flags"; ram_max_mb = $cfg.ram_max_mb }
        $etil = (Get-JvmFlagsList $cfgE) -join " "
        $htmlOk = (Decompress-B64ToBytes $EmbeddedIndexHtmlB64).Length
        $javaOk = (Decompress-B64ToBytes $EmbeddedWebServerJavaB64).Length
        Write-Host "TEST_CONFIG_OK"
        Write-Host "MC=$($cfg.mc_version) LOADER=$($cfg.loader) ARCH=$(Get-CpuArch)"
        Write-Host "MEOWICE_G1GC_LEN=$($g1.Length) MEOWICE_ZGC_LEN=$($zgc.Length) ETIL_LEN=$($etil.Length)"
        Write-Host "EMBED_WEBGUI_BYTES=HTML:$htmlOk,JAVA:$javaOk"
        exit 0
    }
    if ($CliArgs[0] -eq "--run-task") {
        $task = $CliArgs[1]
        $cfg = Load-Config
        switch ($task) {
            "full-auto" {
                Save-Config $cfg
                Install-JavaSilent
                Install-ServerLoaderSilent $cfg.mc_version $cfg.loader
                Install-PlayitSilent
                Extract-WebGuiFiles
                Update-StartupScripts $cfg
            }
            "install-mc" {
                $v = if ($CliArgs.Count -ge 3) { $CliArgs[2] } else { $cfg.mc_version }
                $l = if ($CliArgs.Count -ge 4) { $CliArgs[3] } else { $cfg.loader }
                $cfg.mc_version = $v
                $cfg.loader = $l.ToLower()
                Save-Config $cfg
                Install-JavaSilent
                Install-ServerLoaderSilent $cfg.mc_version $cfg.loader
                Update-StartupScripts $cfg
            }
            "install-mod" {
                $slug = $CliArgs[2]
                Install-ModrinthSilent $slug $cfg.mc_version $cfg.loader
            }
            "install-url" {
                $url = $CliArgs[2]
                $isPlugin = @("paper","purpur","leaf") -contains $cfg.loader
                $dir = if ($isPlugin) { $PluginsDir } else { $ModsDir }
                $name = ([System.IO.Path]::GetFileName(($url -split '\?')[0])) -replace '[^a-zA-Z0-9._-]','_'
                if (-not $name.EndsWith(".jar")) { $name = "custom.jar" }
                Download-Silent $url (Join-Path $dir $name)
            }
            "install-pack" {
                Install-PackSilent $CliArgs[2] $cfg.mc_version $cfg.loader
            }
            "install-playit" {
                Install-PlayitSilent
            }
            "install-webgui" {
                Save-Config $cfg
                Install-JavaSilent
                Extract-WebGuiFiles
                Update-StartupScripts $cfg
            }
            default { throw "Task khong hop le: $task" }
        }
        exit 0
    }
}

