function Show-Header($cfg) {
    Clear-Host
    Write-Host "========================================================================" -ForegroundColor Cyan
    Write-Host "  TRINH CAI DAT & QUAN LY SERVER MINECRAFT (WINDOWS / MAC / LINUX)" -ForegroundColor Cyan
    Write-Host "  MC: $($cfg.mc_version) | Loader: $($cfg.loader.ToUpper()) | Flags: $($cfg.flag_profile.ToUpper()) | RAM: $($cfg.ram_min_mb)-$($cfg.ram_max_mb)MB" -ForegroundColor Yellow
    Write-Host "========================================================================" -ForegroundColor Cyan
}

