    Write-Host "  [3] 1.21.8"
    Write-Host "  [4] 1.21.4"
    Write-Host "  [5] 1.20.4"
    Write-Host "  [6] 1.20.1"
    Write-Host "  [7] Tu nhap phien ban khac (vd: 1.16.5, 1.12.2, 26.1.2)"
    $vc = Read-Host "  Chon phien ban [1-7, Enter = $($cfg.mc_version)]"
    $ver = switch ($vc) {
        "1" { "1.21.11" }
        "2" { "1.21.10" }
        "3" { "1.21.8" }
        "4" { "1.21.4" }
        "5" { "1.20.4" }
        "6" { "1.20.1" }
        "7" { (Read-Host "  Nhap phien ban MC").Trim() }
