    }
    if (-not $ver) { $ver = $cfg.mc_version }

    Write-Host ""
    Write-Host "  --- CHON LOADER / NHAN SERVER ---" -ForegroundColor Green
    Write-Host "  [1] Fabric   (Mod nhe, toi uu TPS)"
    Write-Host "  [2] PaperMC  (Plugin pho bien)"
    Write-Host "  [3] Purpur   (Plugin tuy bien cao)"
    Write-Host "  [4] LeafMC   (Plugin toi uu nhat cho MeowIce Flags)"
    Write-Host "  [5] NeoForge (Mod hien dai 1.20.2+)"
    Write-Host "  [6] Forge    (Mod truyen thong)"
    Write-Host "  [7] Vanilla  (Goc Mojang)"
    $lc = Read-Host "  Chon loader [1-7, Enter = $($cfg.loader)]"
    $loader = switch ($lc) {
        "1" { "fabric" }
        "2" { "paper" }
        "3" { "purpur" }
        "4" { "leaf" }
        "5" { "neoforge" }
