function Menu-ModsPlugins($cfg) {
    while ($true) {
        $cfg = Load-Config
        Write-Host ""
        Write-Host "  === CHE DO 3: CAI DAT GOI MOD / PLUGIN ($($cfg.mc_version) | $($cfg.loader.ToUpper())) ===" -ForegroundColor Cyan
        Write-Host "  [1] Cai goi Mod Toi Uu Co Ban (Fabric API + Lithium + FerriteCore + Spark + Chunky)"
        Write-Host "  [2] Cai goi Plugin Co Ban (Spark + Chunky + ViaVersion + ViaBackwards + LuckPerms)"
        Write-Host "  [3] Cai 1 Mod/Plugin theo ten/slug Modrinth (vd: simple-voice-chat, worldedit)"
        Write-Host "  [4] Cai Mod/Plugin tu duong link URL (.jar)"
        Write-Host "  [5] Xem danh sach Mod/Plugin da cai"
        Write-Host "  [0] Quay lai menu chinh"
        $c = Read-Host "  Lua chon"
        switch ($c) {
            "1" { Invoke-SilentTask "Goi Mod Toi Uu Co Ban" @("install-pack", "mod_opt"); Pause }
            "2" { Invoke-SilentTask "Goi Plugin Co Ban" @("install-pack", "plugin_base"); Pause }
            "3" {
                $slug = (Read-Host "  Nhap slug Modrinth (vd: lithium, spark, luckperms)").Trim()
                if ($slug) { Invoke-SilentTask "Mod/Plugin '$slug'" @("install-mod", $slug) }
                Pause
            }
            "4" {
                $url = (Read-Host "  Dan URL truc tiep file .jar").Trim()
                if ($url) { Invoke-SilentTask "File tu URL" @("install-url", $url) }
                Pause
            }
            "5" {
                Write-Host "  --- Thu muc mods/ ---"
                Get-ChildItem $ModsDir -ErrorAction SilentlyContinue | ForEach-Object { Write-Host "   - $($_.Name)" }
                Write-Host "  --- Thu muc plugins/ ---"
                Get-ChildItem $PluginsDir -ErrorAction SilentlyContinue | ForEach-Object { Write-Host "   - $($_.Name)" }
                Pause
            }
            "0" { return }
        }
    }
}

function Menu-RamAndFlags {
    $cfg = Load-Config
    Write-Host ""
    Write-Host "  === CAU HINH RAM & CHON BO JVM FLAGS ===" -ForegroundColor Cyan
    $rMin = Read-Host "  Nhap RAM Min -Xms (MB) [Enter = $($cfg.ram_min_mb)]"
    $rMax = Read-Host "  Nhap RAM Max -Xmx (MB) [Enter = $($cfg.ram_max_mb)]"
    if ($rMin -match '^\d+$') { $cfg.ram_min_mb = [int]$rMin }
    if ($rMax -match '^\d+$') { $cfg.ram_max_mb = [int]$rMax }

    Write-Host ""
    Write-Host "  Chon bo Startup Flags:"
    Write-Host "  [1] MeowIce Flags - G1GC (Khuyen nghi < 32GB RAM, GraalVM/JDK 21-25)"
    Write-Host "  [2] MeowIce Flags - ZGC  (Server >= 32GB RAM, 10+ CPU Cores)"
    Write-Host "  [3] Etil Minecraft Flags (G1GC toi uu cho Adoptium/HotSpot)"
    Write-Host "  [4] Aikar Flags          (Co dien)"
    Write-Host "  [5] Mac dinh             (Khong dung Flags)"
    $fc = Read-Host "  Chon [1-5, Enter = $($cfg.flag_profile)]"
    $cfg.flag_profile = switch ($fc) {
        "1" { "meowice_g1gc" }
        "2" { "meowice_zgc" }
        "3" { "etil_flags" }
        "4" { "aikar" }
        "5" { "default" }
        default { $cfg.flag_profile }
    }
    Save-Config $cfg
    Update-StartupScripts $cfg
    Write-Host "  [HOAN THANH] Da cap nhat RAM & Flags ($($cfg.flag_profile))!" -ForegroundColor Green
    Pause
}

function Menu-ServerProperties {
    Ensure-EulaAndProperties
    $propPath = Join-Path $ServerDir "server.properties"
    $lines = Get-Content $propPath -Encoding UTF8
    $map = [ordered]@{}
    foreach ($l in $lines) {
        if ($l -match '^\s*([^#=]+?)\s*=\s*(.*)$') { $map[$Matches[1]] = $Matches[2] }
    }
    Write-Host ""
    Write-Host "  === CHINH SUA NHANH SERVER.PROPERTIES ===" -ForegroundColor Cyan
    $om = Read-Host "  Cho phep TK Cracked/TLauncher? (online-mode=false) [y/n, Enter giu nguyen '$($map['online-mode'])']"
    if ($om -eq 'y') { $map['online-mode'] = 'false' } elseif ($om -eq 'n') { $map['online-mode'] = 'true' }
    $mp = Read-Host "  So nguoi choi toi da (max-players) [Enter = $($map['max-players'])]"
    if ($mp -match '^\d+$') { $map['max-players'] = $mp }
    $gm = Read-Host "  Che do choi (survival/creative/adventure) [Enter = $($map['gamemode'])]"
    if ($gm) { $map['gamemode'] = $gm }
    $df = Read-Host "  Do kho (peaceful/easy/normal/hard) [Enter = $($map['difficulty'])]"
    if ($df) { $map['difficulty'] = $df }
    $motd = Read-Host "  Ten Server (motd) [Enter giu nguyen]"
    if ($motd) { $map['motd'] = $motd }

    $out = @("# Minecraft Server Properties")
    foreach ($k in $map.Keys) { $out += "$k=$($map[$k])" }
    Write-Utf8NoBom $propPath (($out -join "`n") + "`n")
    Write-Host "  [HOAN THANH] Da luu server.properties!" -ForegroundColor Green
    Pause
}

function Start-WebGuiPanel {
    $cfg = Load-Config
    if (-not (Test-Path (Join-Path $WebDir "WebServer.java")) -or -not (Get-JavaPath)) {
        Invoke-SilentTask "Giao Dien Quan Ly Web GUI & Java" @("install-webgui")
    }
    $javaExe = Get-JavaPath
    if (-not $javaExe) {
        Write-Host "  [LOI] Khong tim thay Java 21+ de chay Web GUI." -ForegroundColor Red
        Pause; return
    }
    $webJava = Join-Path $WebDir "WebServer.java"
    $port = $cfg.web_port
    Write-Host "  Dang mo Giao Dien Quan Ly Web GUI tai http://127.0.0.1:$port ..." -ForegroundColor Green
    Start-Process -FilePath $javaExe -ArgumentList @($webJava, "--port", "$port") -WorkingDirectory $RootDir | Out-Null
    Start-Sleep -Seconds 2
    Start-Process "http://127.0.0.1:$port"
    Write-Host "  [HOAN THANH] Da mo trinh duyet Web GUI. (Web server dang chay o cua so rieng)" -ForegroundColor Green
    Pause
}

function Start-MinecraftServer($withPlayit) {
    $cfg = Load-Config
    $bat = Join-Path $ServerDir "start_server.bat"
    if (-not (Test-Path $bat)) {
        Write-Host "  [CANH BAO] Chua cai dat Server Minecraft. Hay chon Che Do 1 hoac 2 truoc!" -ForegroundColor Yellow
        Pause; return
    }
    if ($withPlayit) {
        $pExe = Join-Path $PlayitDir "playit.exe"
        if (-not (Test-Path $pExe)) {
            Invoke-SilentTask "Playit.gg Tunnel" @("install-playit")
        }
        if (Test-Path $pExe) {
            Start-Process -FilePath $pExe -WorkingDirectory $PlayitDir
        }
    }
    Write-Host "  Dang khoi dong Server Minecraft ($($cfg.mc_version) | $($cfg.loader.ToUpper()) | $($cfg.flag_profile.ToUpper()))..." -ForegroundColor Green
    & cmd.exe /c $bat
}

function Clean-AllInstalledDirs {
    Write-Host ""
    $ans = Read-Host "  [CANH BAO] Ban chac chan muon XOA HET server, runtime, playit, web_panel, logs? [y/N]"
    if ($ans -eq 'y' -or $ans -eq 'Y') {
        foreach ($p in @($ServerDir, $RuntimeDir, $PlayitDir, $WebDir, $LogsDir, $ConfigFile)) {
            if (Test-Path $p) { Remove-Item -Path $p -Recurse -Force -ErrorAction SilentlyContinue }
        }
        Write-Host "  [HOAN THANH] Da xoa sach toan bo thu muc cai dat!" -ForegroundColor Green
    } else {
        Write-Host "  Da huy thao tac xoa." -ForegroundColor Yellow
    }
    Pause
}

